  </div>
</footer>

<!-- ========================= MODAL ========================= -->
<div class="modal" id="booking" aria-hidden="true">
  <div class="modal__backdrop" data-close></div>
  <div class="modal__card" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
    <button class="modal__close" data-close aria-label="Close">✕</button>
    <div id="bookingFormWrap">
      <span class="eyebrow">Reservation</span>
      <h2 class="h2" id="modalTitle" style="font-size:1.9rem">Book your berth</h2>
      <p class="lead" style="margin-bottom:6px" id="modalService">The Salt Flat Express · departs 21:40 from Salt Flats Platform 4</p>
      <form id="bookingForm">
        <div class="field">
          <label for="bName">Passenger name</label>
          <input id="bName" name="name" type="text" placeholder="As printed on your ticket" required>
        </div>
        <div class="field">
          <label for="bCabin">Cabin class</label>
          <select id="bCabin" name="cabin">
            <option>Reclining Coach — $128</option>
            <option selected>Dune Sleeper Cabin — $284</option>
            <option>Neon Suite — $620</option>
          </select>
        </div>
        <div class="field">
          <label for="bNight">Night of travel</label>
          <input id="bNight" name="night" type="text" placeholder="e.g. 14 → 15 March">
        </div>
        <button class="btn btn--primary btn--block" type="submit" style="margin-top:22px">Confirm berth</button>
        <p class="news-note" style="text-align:center;margin-top:14px">No payment is taken. Dune Line is a fiction.</p>
      </form>
    </div>
  </div>
</div>

<script>
(function(){
  "use strict";

  /* ---------- sticky nav state ---------- */
  var nav = document.getElementById('nav');
  var onScroll = function(){ nav.classList.toggle('scrolled', window.scrollY > 24); };
  onScroll();
  window.addEventListener('scroll', onScroll, {passive:true});

  /* ---------- mobile menu ---------- */
  var toggle = document.getElementById('navToggle');
  var menu = document.getElementById('mobileMenu');
  toggle.addEventListener('click', function(){
    var open = menu.classList.toggle('is-open');
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  });
  menu.addEventListener('click', function(e){
    if(e.target.tagName === 'A'){
      menu.classList.remove('is-open');
      toggle.setAttribute('aria-expanded','false');
    }
  });

  /* ---------- scroll reveal ---------- */
  var revealEls = document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        if(en.isIntersecting){
          en.target.classList.add('in');
          io.unobserve(en.target);
        }
      });
    }, {threshold:.12, rootMargin:'0px 0px -60px 0px'});
    revealEls.forEach(function(el, i){
      el.style.setProperty('--d', (i % 4) * 70 + 'ms');
      io.observe(el);
    });
  } else {
    revealEls.forEach(function(el){ el.classList.add('in'); });
  }

  /* ---------- booking modal ---------- */
  var modal = document.getElementById('booking');
  var formWrap = document.getElementById('bookingFormWrap');
  var modalService = document.getElementById('modalService');
  var bookingForm = document.getElementById('bookingForm');
  var lastFocus = null;

  var services = {
    'The Salt Flat Express':'departs 21:40 from Salt Flats Platform 4 · arrives 12:00',
    'The Long Dusk':'departs 22:15 from Salt Flats Platform 2 · arrives 15:20',
    'The Ember Run':'departs 23:05 from Salt Flats Platform 4 · arrives 11:35',
    'The Nightjar':'departs 00:30 from Salt Flats Platform 1 · arrives 13:15',
    'Reclining Coach':'departs 21:40 from Salt Flats Platform 4 · arrives 12:00',
    'Dune Sleeper Cabin':'departs 21:40 from Salt Flats Platform 4 · arrives 12:00',
    'Neon Suite':'departs 22:15 from Salt Flats Platform 2 · arrives 15:20'
  };

  function openModal(name){
    lastFocus = document.activeElement;
    modalService.textContent = (name || 'Dune Line') + ' · ' + (services[name] || 'nightly departure · berths held 20 minutes');
    formWrap.innerHTML = formWrap.innerHTML; /* reset any previous ticket */
    modal.classList.add('is-open');
    modal.setAttribute('aria-hidden','false');
    document.body.style.overflow = 'hidden';
    setTimeout(function(){
      var first = modal.querySelector('input, select, button:not([data-close])');
      if(first) first.focus();
    }, 60);
  }
  function closeModal(){
    modal.classList.remove('is-open');
    modal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
    if(lastFocus) lastFocus.focus();
  }

  document.addEventListener('click', function(e){
    var trigger = e.target.closest('[data-book]');
    if(trigger){
      e.preventDefault();
      openModal(trigger.getAttribute('data-book'));
      return;
    }
    if(e.target.closest('[data-close]')) closeModal();
  });

  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape' && modal.classList.contains('is-open')) closeModal();
  });

  /* ---------- booking submit -> faux ticket ---------- */
  bookingForm.addEventListener('submit', function(e){
    e.preventDefault();
    var name = (document.getElementById('bName').value || 'Traveller').trim();
    var cabin = document.getElementById('bCabin').value;
    var night = (document.getElementById('bNight').value || 'next available').trim();
    var price = cabin.split('—')[1] ? cabin.split('—')[1].trim() : '—';
    var code = 'DL-' + Math.random().toString(36).slice(2,7).toUpperCase();

    formWrap.innerHTML =
      '<span class="eyebrow">Berth confirmed</span>' +
      '<h2 class="h2" style="font-size:1.9rem">See you at dusk</h2>' +
      '<div class="ticket">' +
        '<div class="ticket__row"><span>Passenger</span><span>' + name.replace(/[<>&]/g,'') + '</span></div>' +
        '<div class="ticket__row"><span>Service</span><span>' + (modalService.textContent.split('·')[0].trim()) + '</span></div>' +
        '<div class="ticket__row"><span>Class</span><span>' + cabin.replace(/[<>&]/g,'').split('—')[0].trim() + '</span></div>' +
        '<div class="ticket__row"><span>Night</span><span>' + night.replace(/[<>&]/g,'') + '</span></div>' +
        '<div class="ticket__row"><span>Fare</span><span>' + price.replace(/[<>&]/g,'') + '</span></div>' +
        '<div class="ticket__code">' + code + '</div>' +
      '</div>' +
      '<button class="btn btn--ghost btn--block" type="button" id="doneBtn" style="margin-top:18px">Done</button>' +
      '<p class="news-note" style="text-align:center;margin-top:12px">Dune Line is a fictional railway. Nothing was booked, but the desert is waiting.</p>';

    document.getElementById('doneBtn').addEventListener('click', function(){
      window.location.reload();
    });
  });

  /* ---------- newsletter ---------- */
  var newsForm = document.getElementById('newsForm');
  var newsNote = document.getElementById('newsNote');
  newsForm.addEventListener('submit', function(e){
    e.preventDefault();
    var email = document.getElementById('newsEmail').value.trim();
    if(!email){ newsNote.textContent = 'Please add an email address first.'; return; }
    newsForm.innerHTML = '<span class="badge badge--cyan">Subscribed</span>';
    newsNote.textContent = 'Thank you — your first departure note arrives on the 1st.';
  });
})();
</script>
</body>
</html>
